800	  // 操作记录从不删除（撤销也保留），标识序号集合必须恰好为 1..batchSeq
801	  for (let i = 1; i <= store.batchSeq; i++) {
802	    if (!batchOpNums.has(i)) bad(`批量改期操作记录缺号：找不到标识序号 ${i} 的记录`);
803	  }
