805	  // iCalendar 导入身份记录：UID 唯一且非空。两类身份：
806	  //   独立事件 -> bookingId 指向一项普通预约；
807	  //   按周重复事件 -> seriesId 指向一个系列，occurrences 按原发生顺序记录每个
808	  //   未排除发生的原开始时间与对应成员（count/exdates 为首次请求的重复参数）。
809	  // 成员预约与系列均不得被另一条导入记录重复关联；快照自身须合法（真实时间、
810	  // 结束晚于开始、资源已知且不重复、COUNT 合法、排除集合与发生映射自洽）。
811	  // 成员现状（被改期/取消）与首次请求不同不算损坏。
812	  const importUids = new Set<string>();
813	  const importLinkedBookings = new Set<string>();
814	  const importLinkedSeries = new Set<string>();
815	  const claimBooking = (uid: string, bId: string, at: string): void => {
816	    if (!bookingById.has(bId)) bad(`${at}(UID “${uid}”) 关联了未知预约: ${bId}`);
817	    if (importLinkedBookings.has(bId)) {
818	      bad(`${at}(UID “${uid}”) 预约 ${bId} 已被另一条导入记录关联（一项预约只能对应一个 UID）`);
819	    }
820	    importLinkedBookings.add(bId);
821	  };
822	  rawImports.forEach((item, idx) => {
823	    const at = `imports[${idx}]`;
824	    if (typeof item !== 'object' || item === null || Array.isArray(item)) bad(`${at} 必须是对象`);
825	    const im = item as Record<string, unknown>;
826	    if (typeof im.uid !== 'string' || im.uid === '') bad(`${at}.uid 必须是非空字符串`);
827	    if (importUids.has(im.uid)) bad(`导入记录 UID 重复: ${im.uid}`);
828	    importUids.add(im.uid);
829	    const uid = im.uid;
830	
831	    const hasBooking = im.bookingId !== undefined;
832	    const hasSeries = im.seriesId !== undefined;
833	    if (hasBooking === hasSeries) {
834	      bad(`${at}(UID “${uid}”) 必须恰好提供 bookingId（独立事件）或 seriesId（重复事件）之一`);
835	    }
836	    if (typeof im.start !== 'string' || typeof im.end !== 'string') {
837	      bad(`${at}(UID “${uid}”) 快照起止时间必须是字符串`);
838	    }
839	    const s = parseDateTime(im.start as string, `${at}(UID “${uid}”).start`);
840	    const e = parseDateTime(im.end as string, `${at}(UID “${uid}”).end`);
841	    if (e <= s) bad(`${at}(UID “${uid}”) 快照结束必须晚于开始`);
842	    if (!Array.isArray(im.resourceIds) || im.resourceIds.length === 0) {
843	      bad(`${at}(UID “${uid}”).resourceIds 必须是非空数组`);
844	    }
845	    const rids = im.resourceIds as unknown[];
846	    const rseen = new Set<string>();
847	    rids.forEach((rid) => {
848	      if (typeof rid !== 'string' || !resourceIds.has(rid)) {
849	        bad(`${at}(UID “${uid}”) 快照引用了未知资源: ${String(rid)}`);
850	      }
851	      if (rseen.has(rid)) bad(`${at}(UID “${uid}”) 快照资源重复: ${rid}`);
852	      rseen.add(rid);
853	    });
854	
855	    const rec: ImportRec = {
856	      uid,
857	      start: im.start as string,
858	      end: im.end as string,
859	      resourceIds: [...rseen].sort(),
860	    };
861	
862	    if (hasBooking) {
863	      // 独立事件身份：不得携带重复字段
864	      if (typeof im.bookingId !== 'string' || !/^B\d{4,}$/.test(im.bookingId)) {
865	        bad(`${at}(UID “${uid}”).bookingId 非法: ${String(im.bookingId)}`);
866	      }
867	      for (const k of ['count', 'exdates', 'occurrences']) {
868	        if (im[k] !== undefined) bad(`${at}(UID “${uid}”) 独立事件身份不应携带 ${k}`);
869	      }
870	      claimBooking(uid, im.bookingId as string, at);
871	      rec.bookingId = im.bookingId as string;
872	      store.imports.push(rec);
873	      return;
874	    }
875	
876	    // 重复事件身份
877	    if (typeof im.seriesId !== 'string' || !/^S\d{4,}$/.test(im.seriesId)) {
878	      bad(`${at}(UID “${uid}”).seriesId 非法: ${String(im.seriesId)}`);
879	    }
880	    if (!seriesIds.has(im.seriesId)) {
881	      bad(`${at}(UID “${uid}”) 关联了未知系列: ${im.seriesId}`);
882	    }
883	    if (importLinkedSeries.has(im.seriesId)) {
884	      bad(`${at}(UID “${uid}”) 系列 ${im.seriesId} 已被另一条导入记录关联（一个系列只能对应一个 UID）`);
885	    }
886	    importLinkedSeries.add(im.seriesId);
887	    rec.seriesId = im.seriesId;
888	
889	    if (!isInt(im.count) || im.count < 1 || im.count > MAX_OCCURRENCES) {
890	      bad(`${at}(UID “${uid}”).count 必须是 1..${MAX_OCCURRENCES} 的整数`);
891	    }
892	    rec.count = im.count;
893	    if (!Array.isArray(im.exdates)) bad(`${at}(UID “${uid}”).exdates 必须是数组`);
894	    const exSet = new Set<string>();
895	    (im.exdates as unknown[]).forEach((xv, j) => {
896	      if (typeof xv !== 'string') bad(`${at}(UID “${uid}”).exdates[${j}] 必须是时间字符串`);
897	      parseDateTime(xv, `${at}(UID “${uid}”).exdates[${j}]`);
898	      if (exSet.has(xv)) bad(`${at}(UID “${uid}”) 排除时间重复: ${xv}`);
899	      exSet.add(xv);
900	    });
901	    rec.exdates = [...exSet].sort();
902	
903	    if (!Array.isArray(im.occurrences) || im.occurrences.length === 0) {
904	      bad(`${at}(UID “${uid}”).occurrences 必须是非空数组（全部发生被排除的首次请求非法）`);
905	    }
906	    const occTimes = new Set<string>();
907	    const occs: Array<{start: string; bookingId: string}> = [];
908	    (im.occurrences as unknown[]).forEach((ov, j) => {
909	      const oat = `${at}(UID “${uid}”).occurrences[${j}]`;
910	      if (typeof ov !== 'object' || ov === null || Array.isArray(ov)) bad(`${oat} 必须是对象`);
911	      const o = ov as Record<string, unknown>;
912	      for (const k of Object.keys(o)) {
913	        if (k !== 'start' && k !== 'bookingId') bad(`${oat} 存在未知字段 “${k}”`);
914	      }
915	      if (typeof o.start !== 'string') bad(`${oat}.start 必须是时间字符串`);
916	      parseDateTime(o.start, `${oat}.start`);
917	      if (occTimes.has(o.start)) bad(`${at}(UID “${uid}”) 原发生时间重复: ${o.start}`);
918	      occTimes.add(o.start);
919	      if (typeof o.bookingId !== 'string' || !/^B\d{4,}$/.test(o.bookingId)) {
920	        bad(`${oat}.bookingId 非法: ${String(o.bookingId)}`);
921	      }
922	      claimBooking(uid, o.bookingId, at);
923	      occs.push({start: o.start, bookingId: o.bookingId});
924	    });
925	
926	    // 映射自洽性：按首项与 COUNT 展开全部原发生（须在四位年份内），
927	    // 未排除发生必须恰好等于 occurrences（时间集合一致、顺序按发生先后）
928	    const expectedAll: string[] = [];
929	    for (let i = 0; i < rec.count; i++) {
930	      const raw = formatDateTime(s + i * 7 * 1440);
931	      if (raw === null) bad(`${at}(UID “${uid}”) 重复展开超出四位年份范围（0001-9999）`);
932	      expectedAll.push(raw);
933	    }
934	    const expectedKept = expectedAll.filter((t) => !exSet.has(t));
935	    const excludedNotInSeries = [...exSet].filter((t) => !expectedAll.includes(t));
936	    if (excludedNotInSeries.length > 0) {
937	      bad(`${at}(UID “${uid}”) 排除时间不匹配任何原发生: ${excludedNotInSeries.join('、')}`);
938	    }
939	    if (occs.length !== expectedKept.length || occs.some((o, j) => o.start !== expectedKept[j])) {
940	      bad(
941	        `${at}(UID “${uid}”) 发生映射缺漏或重复：COUNT=${rec.count}、排除 ${exSet.size} 项` +
942	          `时应有 ${expectedKept.length} 个未排除发生且按发生顺序排列`,
943	      );
944	    }
945	    // 成员必须恰好为所关联系列的全部成员（1:1：系列成员不重不漏）
946	    const seriesMembers = new Set(
947	      store.bookings.filter((b) => b.seriesId === rec.seriesId).map((b) => b.id),
948	    );
949	    for (const o of occs) {
950	      if (!seriesMembers.has(o.bookingId)) {
951	        bad(`${at}(UID “${uid}”) 成员 ${o.bookingId} 不属于系列 ${rec.seriesId}`);
952	      }
953	    }
954	    if (occs.length !== seriesMembers.size) {
955	      bad(`${at}(UID “${uid}”) 系列 ${rec.seriesId} 存在未登记在 occurrences 中的成员（系列与发生映射必须一一对应）`);
956	    }
957	    rec.occurrences = occs;
958	    store.imports.push(rec);
959	  });
960	
961	  store.resources.sort((a, b) => a.id.localeCompare(b.id));
962	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
963	  store.series.sort((a, b) => a.id.localeCompare(b.id));
964	  store.waitlist.sort((a, b) => a.seq - b.seq || a.id.localeCompare(b.id));
965	  store.closures.sort((a, b) => a.id.localeCompare(b.id));
966	  store.batchOps.sort((a, b) => Number(a.id.slice(1)) - Number(b.id.slice(1)));
967	  store.imports.sort((a, b) => a.uid.localeCompare(b.uid));
968	  return store;
969	}
