1008	// ---------------------------------------------------------------------------
1009	// 多进程写入保护（同一数据文件全局互斥）
1010	//
1011	// 所有修改入口在读取数据前先取得本数据文件的写入保护（锁文件，wx 独占创建），
1012	// 保护覆盖读取决策所需状态、业务校验、标识分配与原子保存全过程，命令结束时
1013	// 统一释放（正常结束、校验失败、保存失败均释放）。锁文件按数据文件的规范路径
1014	// 命名：相对路径、绝对路径与含 ./.. 的等价写法共享同一把锁；不同数据文件
1015	// 互不影响；数据文件尚不存在时同样受保护。竞争可等待，但 5 秒内未取得即以
1016	// 退出码 1 报告占用（可重试）。进程异常退出会留下残留锁：recover-lock 仅在
1017	// 确认原写入进程已退出后解除，存活或无法确认一律拒绝，不按保护存在时长抢占。
1018	//
1019	// 交接互斥：取得（wx 独占创建）、释放（仅删自己取得的那份）、恢复三者都不得
1020	// 误删他人的保护。恢复入口之间以恢复协调文件（<锁文件>.recover，wx 独占创建）
1021	// 互斥：任一时刻至多一个恢复者持有协调文件，持有者在互斥内重新核对目标后才
1022	// 删除锁文件——持有协调文件期间，原持有者已确认退出（不会再释放）、其他恢复者
1023	// 进不了互斥、新写入者只能在锁文件不存在时取得（wx），因此互斥内的删除恰好
1024	// 删除本次确认的那一份残留保护，绝不误删新写入者已取得的保护；发现目标更替
1025	// （锁已易主或已消失）则以退出码 1 说明原因或按无操作退出 0，不宣称解除新保护。
1026	// 恢复者异常退出会留下残留协调文件：下一恢复入口在确认其持有者已退出后清理
1027	// 并重试，无需人工删文件。
1028	// ---------------------------------------------------------------------------
1029	
1030	const LOCK_TIMEOUT_MS = 5000; // 取得写入保护的最长等待时间
1031	const LOCK_RETRY_MS = 40; // 竞争重试间隔（含随机抖动，避免齐步）
1032	
1033	// 数据文件的规范路径：解析相对路径与 ./..，并尽量解析符号链接
1034	// （文件尚不存在时解析其父目录，父目录也不可用时退化为绝对路径）
1035	function canonicalDataPath(file: string): string {
1036	  const abs = resolve(file);
1037	  try {
1038	    return realpathSync(abs);
1039	  } catch {
1040	    try {
1041	      return join(realpathSync(dirname(abs)), basename(abs));
1042	    } catch {
1043	      return abs;
1044	    }
1045	  }
1046	}
1047	
1048	// 锁文件路径：与数据文件同目录、按规范路径命名；文件名长度受限（如 255 字节）
1049	// 时退化为同目录下的散列锁名，同一数据文件的所有进程仍共享同一把锁
1050	function lockPathFor(file: string): string {
1051	  const canonical = canonicalDataPath(file);
1052	  const primary = `${canonical}.lock`;
1053	  if (Buffer.byteLength(basename(primary), 'utf8') <= 250) return primary;
1054	  const hash = createHash('sha256').update(canonical).digest('hex').slice(0, 24);
1055	  return join(dirname(canonical), `.shiftbook-${hash}.lock`);
1056	}
1057	
1058	// 恢复协调文件路径：恢复入口之间的互斥（<锁文件>.recover），与锁文件同样
1059	// 按规范路径命名并受文件名长度限制（超限时同样退化为同目录散列名）
1060	function recoveryPathFor(file: string): string {
1061	  const lockPath = lockPathFor(file);
1062	  const primary = `${lockPath}.recover`;
1063	  if (Buffer.byteLength(basename(primary), 'utf8') <= 250) return primary;
1064	  const canonical = canonicalDataPath(file);
1065	  const hash = createHash('sha256').update(`${canonical}recover`).digest('hex').slice(0, 24);
1066	  return join(dirname(canonical), `.shiftbook-${hash}.recover`);
1067	}
