1069	interface LockInfo {
1070	  pid: number; // 取得保护的进程
1071	  host: string; // 取得保护的主机（恢复时只能确认本机进程）
1072	  dataFile: string; // 被保护数据文件的规范路径
1073	  acquiredAt: string; // 取得时间（ISO 文本，仅供诊断，不作为解除依据）
1074	}
1075	
1076	function currentLockInfo(file: string): LockInfo {
1077	  return {
1078	    pid: process.pid,
1079	    host: hostname(),
1080	    dataFile: canonicalDataPath(file),
1081	    acquiredAt: new Date().toISOString(),
1082	  };
1083	}
