1085	// 解析锁/协调文件内容；无法辨认（非 JSON、缺字段或字段非法）返回 null
1086	function parseLockInfo(text: string): LockInfo | null {
1087	  try {
1088	    const parsed = JSON.parse(text) as LockInfo;
1089	    if (!Number.isInteger(parsed.pid) || parsed.pid <= 0 || typeof parsed.host !== 'string') {
1090	      return null;
1091	    }
1092	    return parsed;
1093	  } catch {
1094	    return null;
1095	  }
1096	}
