1098	// 确认 info 所指保护的原持有进程已退出：存活、非本机、内容无法辨认或查询异常
1099	// 均抛出 BizError 拒绝，不按保护存在时长抢占；确认退出后返回该 info
1100	function assertLockStale(info: LockInfo | null, lockPath: string): LockInfo {
1101	  if (info === null) {
1102	    throw new BizError(
1103	      `写入保护文件 ${lockPath} 内容无法辨认，无法确认原写入进程，拒绝解除（请人工核查后自行处理该文件）`,
1104	    );
1105	  }
1106	  if (info.host !== hostname()) {
1107	    throw new BizError(
1108	      `写入保护由另一台主机（${info.host}）的进程 ${info.pid} 取得，本机无法确认其是否已退出，拒绝解除`,
1109	    );
1110	  }
1111	  let alive = false;
1112	  try {
1113	    process.kill(info.pid, 0);
1114	    alive = true;
1115	  } catch (err) {
1116	    if ((err as NodeJS.ErrnoException).code !== 'ESRCH') {
1117	      throw new BizError(`无法确认原写入进程 ${info.pid} 是否已退出（无权限查询），拒绝解除写入保护`);
1118	    }
1119	  }
1120	  if (alive) {
1121	    throw new BizError(
1122	      `写入保护仍由运行中的进程 ${info.pid} 持有（始于 ${info.acquiredAt}），拒绝解除；` +
1123	        '不按保护存在时长抢占，请等待其结束，或确认其已退出后重试',
1124	    );
1125	  }
1126	  return info;
1127	}
