1129	// 测试同步点（仅当环境变量 SHIFTBOOK_TEST_SYNC_DIR 指向某目录时启用）：
1130	// 到达指定步骤时写入 <dir>/<name>.ready（内容为进程标识），并等待 <dir>/<name>.go
1131	// 出现后继续，供回归测试以真实子进程精确控制取得/恢复交接的时序（明确同步点，
1132	// 而非随机延时）。正常使用不设置该变量，完全无开销。
1133	async function testSyncPoint(name: string): Promise<void> {
1134	  const dir = process.env.SHIFTBOOK_TEST_SYNC_DIR;
1135	  if (!dir) return;
1136	  const go = join(dir, `${name}.go`);
1137	  await writeFile(join(dir, `${name}.ready`), `${process.pid}\n`, 'utf8');
1138	  const deadline = Date.now() + 30000;
1139	  for (;;) {
1140	    try {
1141	      await readFile(go, 'utf8');
1142	      return;
1143	    } catch (err) {
1144	      if ((err as NodeJS.ErrnoException).code !== 'ENOENT') {
1145	        throw new BizError(`测试同步点 ${name} 无法读取: ${(err as Error).message}`);
1146	      }
1147	      if (Date.now() >= deadline) throw new BizError(`测试同步点 ${name} 等待超时`);
1148	      await new Promise((r) => setTimeout(r, 10));
1149	    }
1150	  }
1151	}
