1153	// 本进程当前持有的锁（一次命令至多一把；main 统一释放）
1154	let heldLockPath: string | null = null;
1155	
1156	async function acquireWriteLock(file: string): Promise<void> {
1157	  if (heldLockPath !== null) return;
1158	  const lockPath = lockPathFor(file);
1159	  const content = JSON.stringify(currentLockInfo(file)) + '\n';
1160	  const deadline = Date.now() + LOCK_TIMEOUT_MS;
1161	  for (;;) {
1162	    try {
1163	      await writeFile(lockPath, content, {encoding: 'utf8', flag: 'wx'});
1164	      heldLockPath = lockPath;
1165	      return;
1166	    } catch (err) {
1167	      if ((err as NodeJS.ErrnoException).code !== 'EEXIST') {
1168	        throw new BizError(`无法取得数据文件写入保护（锁文件 ${lockPath}）：${(err as Error).message}`);
1169	      }
1170	      if (Date.now() >= deadline) {
1171	        let owner = '';
1172	        try {
1173	          const info = JSON.parse(await readFile(lockPath, 'utf8')) as LockInfo;
1174	          owner = `（当前由进程 ${info.pid} 持有，始于 ${info.acquiredAt}）`;
1175	        } catch {
1176	          // 占用信息不可读不影响“被占用”的结论
1177	        }
1178	        throw new BizError(
1179	          `数据文件 ${file} 正被其他进程占用${owner}：${LOCK_TIMEOUT_MS / 1000} 秒内未能取得写入保护，` +
1180	            '本次未做任何改动，可稍后重试；若确认原写入进程已异常退出，可使用 recover-lock 解除残留保护',
1181	        );
1182	      }
1183	      await new Promise((r) => setTimeout(r, LOCK_RETRY_MS + Math.floor(Math.random() * LOCK_RETRY_MS)));
1184	    }
1185	  }
1186	}
