1188	// 释放本进程取得的保护；仅删除自己创建的锁文件，绝不动其他进程后来取得的保护
1189	async function releaseWriteLock(): Promise<void> {
1190	  const lockPath = heldLockPath;
1191	  if (lockPath === null) return;
1192	  heldLockPath = null;
1193	  try {
1194	    const info = JSON.parse(await readFile(lockPath, 'utf8')) as LockInfo;
1195	    if (info.pid !== process.pid || info.host !== hostname()) return;
1196	    await unlink(lockPath);
1197	  } catch {
1198	    // 锁文件已不存在或不可读：不影响本次命令的结果
1199	  }
1200	}
