1210	// 本地恢复入口：仅确认原写入进程已退出时才解除残留保护；存活或无法确认一律
1211	// 明确拒绝，不按保护存在时长抢占。不重放旧命令，不改业务数据或标识计数。
1212	//
1213	// 交接安全：恢复者之间以恢复协调文件互斥（wx 独占创建，任一时刻至多一个
1214	// 恢复者），持有者在互斥内重新核对目标后才删除锁文件。持有协调文件期间：
1215	// 原持有进程已确认退出（不会再释放该锁）、其他恢复者进不了互斥、新写入者
1216	// 只能在锁文件不存在时取得（wx 独占创建）——因此互斥内的 unlink 恰好删除
1217	// 本次确认的那一份残留保护，绝不误删新写入者后来取得的保护；发现目标更替
1218	// （锁已易主或已消失）以退出码 1 说明原因或按无操作退出 0，不宣称解除新保护。
1219	// 恢复者异常退出留下的残留协调文件，由下一恢复入口在确认其持有者退出后清理，
1220	// 无需人工删文件。
1221	async function cmdRecoverLock(args: string[]): Promise<void> {
1222	  const {values, positionals} = parseFlags(args, []);
1223	  if (values.size > 0) {
1224	    throw new UsageError(`recover-lock 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`);
1225	  }
1226	  if (positionals.length > 0) {
1227	    throw new UsageError('用法: recover-lock（确认原写入进程已退出后，解除本数据文件的残留写入保护）');
1228	  }
1229	
1230	  const file = activeDataFile;
1231	  const lockPath = lockPathFor(file);
1232	  const recoveryPath = recoveryPathFor(file);
1233	
1234	  // 读取锁文件：undefined = 不存在；null = 内容无法辨认
1235	  const readLockInfo = async (): Promise<LockInfo | null | undefined> => {
1236	    let text: string;
1237	    try {
1238	      text = await readFile(lockPath, 'utf8');
1239	    } catch (err) {
1240	      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return undefined;
1241	      throw new BizError(`无法读取写入保护文件 ${lockPath}: ${(err as Error).message}`);
1242	    }
1243	    return parseLockInfo(text);
1244	  };
1245	
1246	  // 第一次检查（不创建任何协调状态）：无保护直接退出 0 且无操作；
1247	  // 明显不可恢复（存活、非本机、无法辨认、查询异常）直接拒绝
1248	  const first = await readLockInfo();
1249	  if (first === undefined) {
1250	    console.log(`数据文件 ${file} 没有残留写入保护，无需恢复。`);
1251	    return;
1252	  }
1253	  assertLockStale(first, lockPath);
1254	
1255	  // 取得恢复互斥（协调文件，wx 独占创建）：保证“核对目标”与“解除保护”之间
1256	  // 没有其他恢复者插入。已有协调文件时：持有者存活则退出 1（不重复解除）；
1257	  // 确认持有者已退出则清理其残留协调文件后重试（恢复者异常退出的交接清理）。
1258	  const myInfo = JSON.stringify(currentLockInfo(file)) + '\n';
1259	  for (;;) {
1260	    try {
1261	      await writeFile(recoveryPath, myInfo, {encoding: 'utf8', flag: 'wx'});
1262	      break;
1263	    } catch (err) {
1264	      if ((err as NodeJS.ErrnoException).code !== 'EEXIST') {
1265	        throw new BizError(`无法取得恢复互斥（协调文件 ${recoveryPath}）：${(err as Error).message}`);
1266	      }
1267	      let otherText: string;
1268	      try {
1269	        otherText = await readFile(recoveryPath, 'utf8');
1270	      } catch (readErr) {
1271	        if ((readErr as NodeJS.ErrnoException).code === 'ENOENT') continue; // 刚好被清理，重试
1272	        throw new BizError(`无法读取恢复协调文件 ${recoveryPath}: ${(readErr as Error).message}`);
1273	      }
1274	      const other = parseLockInfo(otherText);
1275	      if (other === null) {
1276	        throw new BizError(
1277	          `恢复协调文件 ${recoveryPath} 内容无法辨认，无法确认另一恢复进程是否存活，拒绝继续（请人工核查后自行处理该文件）`,
1278	        );
1279	      }
1280	      if (other.host !== hostname()) {
1281	        throw new BizError(
1282	          `恢复协调文件由另一台主机（${other.host}）的进程 ${other.pid} 取得，本机无法确认其是否已退出，拒绝继续`,
1283	        );
1284	      }
1285	      let otherAlive = false;
1286	      try {
1287	        process.kill(other.pid, 0);
1288	        otherAlive = true;
1289	      } catch (killErr) {
1290	        if ((killErr as NodeJS.ErrnoException).code !== 'ESRCH') {
1291	          throw new BizError(`无法确认另一恢复进程 ${other.pid} 是否已退出（无权限查询），拒绝继续`);
1292	        }
1293	      }
1294	      if (otherAlive) {
1295	        throw new BizError(
1296	          `另一恢复进程 ${other.pid} 正在处理本数据文件的写入保护，本次不重复解除；请等待其结束后重试`,
1297	        );
1298	      }
1299	      // 另一恢复者已确认退出：清理其残留协调文件（可能刚好被他人清理，忽略失败）
1300	      await unlink(recoveryPath).catch(() => {});
1301	    }
1302	  }
1303	
1304	  // 持有恢复互斥：此刻起其他恢复者进不了互斥；原持有进程已确认退出不会再释放；
1305	  // 新写入者只能在锁文件不存在时取得（wx）。因此在互斥内重新核对目标后的删除，
1306	  // 恰好删除本次确认的那一份残留保护。
1307	  try {
1308	    const second = await readLockInfo();
1309	    if (second === undefined) {
1310	      console.log('残留写入保护已被解除（可能由另一恢复入口处理），无需重复操作。');
1311	      return;
1312	    }
1313	    // 目标更替（旧保护已被解除、新写入者取得保护）在此拒绝：存活即退出 1，
1314	    // 绝不删除新写入者的保护，也不宣称解除
1315	    const info = assertLockStale(second, lockPath);
1316	    await testSyncPoint('recover-before-unlock'); // 测试钩子：删除前的交接观察点
1317	    await unlink(lockPath);
1318	    console.log(
1319	      `已解除数据文件 ${file} 的残留写入保护（原写入进程 ${info.pid} 已确认退出）。` +
1320	        '未重放任何旧命令，数据文件、业务记录与标识计数均未改动。',
1321	    );
1322	  } finally {
1323	    // 释放恢复互斥：仅删除自己取得的那一份协调文件（内容核对为本进程）
1324	    try {
1325	      const info = parseLockInfo(await readFile(recoveryPath, 'utf8'));
1326	      if (info !== null && info.pid === process.pid && info.host === hostname()) {
1327	        await unlink(recoveryPath);
1328	      }
1329	    } catch {
1330	      // 协调文件已不存在或不可读：不影响本次恢复的结果
1331	    }
1332	  }
1333	}
