1339	function formatResourceIds(store: Store, ids: string[]): string {
1340	  return ids
1341	    .map((id) => {
1342	      const r = store.resources.find((x) => x.id === id);
1343	      return r ? `${id}（${r.name}）` : id;
1344	    })
1345	    .join('、');
