1348	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
1349	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
1350	  const problems: string[] = [];
1351	  const seen = new Set<string>();
1352	  const dupes: string[] = [];
1353	  for (const id of rawIds) {
1354	    if (seen.has(id)) {
1355	      if (!dupes.includes(id)) dupes.push(id);
1356	    }
1357	    seen.add(id);
1358	  }
1359	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
1360	
1361	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
1362	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
1363	
1364	  if (problems.length > 0) throw new BizError(problems.join('\n'));
1365	  return [...seen].sort();
1366	}
