1368	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
1369	  return mergeIntervals(
1370	    r.open.map(
1371	      ([s, e]) =>
1372	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
1373	    ),
1374	  );
1375	}
