1377	// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
1378	function subtractSegments(
1379	  segments: Array<[number, number]>,
1380	  cuts: Array<[number, number]>,
1381	): Array<[number, number]> {
1382	  let result = segments;
1383	  for (const [cs, ce] of mergeIntervals(cuts)) {
1384	    const next: Array<[number, number]> = [];
1385	    for (const [s, e] of result) {
1386	      if (ce <= s || e <= cs) {
1387	        next.push([s, e]);
1388	        continue;
1389	      }
1390	      if (s < cs) next.push([s, cs]);
1391	      if (ce < e) next.push([ce, e]);
1392	    }
1393	    result = next;
1394	  }
1395	  return result;
1396	}
