1398	// 某资源的有效停用记录（按开始时间、标识排序）
1399	function activeClosuresOf(store: Store, resourceId: string): ClosureRec[] {
1400	  return store.closures
1401	    .filter((c) => c.resourceId === resourceId && c.status === 'active')
1402	    .sort(
1403	      (a, b) =>
1404	        parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
1405	        a.id.localeCompare(b.id),
1406	    );
1407	}
