1424	// 找出实际可用时间（开放扣除有效停用）不能完整覆盖 [startMin, endMin) 的资源
1425	function findCoverageGaps(
1426	  store: Store,
1427	  ids: string[],
1428	  startMin: number,
1429	  endMin: number,
1430	): CoverageGap[] {
1431	  const gaps: CoverageGap[] = [];
1432	  for (const id of ids) {
1433	    const r = store.resources.find((x) => x.id === id)!;
1434	    if (isFullyCovered(availableSegmentsOf(store, r), startMin, endMin)) continue;
1435	    const closures = activeClosuresOf(store, id).filter((c) => {
1436	      const cs = parseDateTime(c.start, '停用开始时间');
1437	      const ce = parseDateTime(c.end, '停用结束时间');
1438	      return cs < endMin && startMin < ce;
1439	    });
1440	    gaps.push({id, r, closures});
1441	  }
1442	  return gaps;
1443	}
