1445	// 开放不足资源的统一展示：资源行 + 相关有效停用（标识与时间）
1446	function gapLines(gaps: CoverageGap[], indent: string): string[] {
1447	  const lines: string[] = [];
1448	  for (const g of gaps) {
1449	    lines.push(`${indent}- ${g.id}（${g.r.name}）`);
1450	    for (const c of g.closures) {
1451	      lines.push(`${indent}  相关有效停用: ${c.id}（${c.start} → ${c.end}）`);
1452	    }
1453	  }
1454	  return lines;
1455	}
