1473	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
1474	function findConflicts(
1475	  store: Store,
1476	  ids: string[],
1477	  startMin: number,
1478	  endMin: number,
1479	  excludeBookingId?: string,
1480	): Conflict[] {
1481	  const wanted = new Set(ids);
1482	  const conflicts: Conflict[] = [];
1483	  for (const b of store.bookings) {
1484	    if (b.status !== 'active') continue;
1485	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
1486	    const bStart = parseDateTime(b.start, '预约开始时间');
1487	    const bEnd = parseDateTime(b.end, '预约结束时间');
1488	    const overlap = bStart < endMin && startMin < bEnd;
1489	    if (!overlap) continue;
1490	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
1491	    if (shared.length > 0) conflicts.push({booking: b, shared});
1492	  }
1493	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
1494	  return conflicts;
1495	}
