1497	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
1498	  if (conflicts.length === 0) return;
1499	  const lines = conflicts.map(
1500	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
1501	  );
1502	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
1503	}
