1506	// 多项预约目标的统一批次校验（无写入副作用）
1507	//
1508	// 创建系列、批量改期、安全撤销与 iCalendar 导入共用本套逻辑，不再各自重复
1509	// 整批可行性循环。校验针对“全部目标生效后”的安排，统一三类检查：
1510	//   1) 实际可用覆盖：开放区间重叠或相接合并后扣除有效停用并集，须连续覆盖目标；
1511	//   2) 批外占用：批外有效预约（已取消不占用）与目标的共同资源时间重叠；
1512	//   3) 批内冲突：本批各目标彼此之间的共同资源时间重叠。
1513	// 区间一律左闭右开，端点相接可行；仅共同资源重叠才算冲突。
1514	// 本函数只读取数据与目标，绝不修改目标、业务记录或标识计数；
1515	// 全部失败项一次性收集（批内冲突在双方各自的失败项中都出现），
1516	// 诊断的业务定位（成员时间/预约标识/UID）与报告顺序由各入口负责。
1517	// ---------------------------------------------------------------------------
1518	
1519	interface ValidationTarget {
1520	  startMin: number;
1521	  endMin: number;
1522	  resourceIds: string[]; // 已校验、按标识排序的完整目标资源集合
1523	}
1524	
1525	interface BatchTargetFailure {
1526	  index: number; // 目标数组下标（0 基）；报告顺序与业务定位由入口决定
1527	  gaps: CoverageGap[]; // 实际可用时间不能完整覆盖目标的资源及相关有效停用
1528	  external: Conflict[]; // 与批外有效预约的冲突（按预约标识排序）
1529	  internal: Array<{otherIndex: number; shared: string[]}>; // 批内冲突（双方互见）
1530	}
1531	
1532	// excludeBookingIds：本批涉及预约的标识，其当前占用不计入批外占用
1533	// （改期与撤销据此允许整批交换时段和资源；系列与导入传空集合）
1534	function validateBatchTargets(
1535	  store: Store,
1536	  targets: ReadonlyArray<ValidationTarget>,
1537	  excludeBookingIds: ReadonlySet<string> = new Set<string>(),
1538	): BatchTargetFailure[] {
1539	  const failures: BatchTargetFailure[] = [];
1540	  for (let i = 0; i < targets.length; i++) {
1541	    const t = targets[i];
1542	    const gaps = findCoverageGaps(store, t.resourceIds, t.startMin, t.endMin);
1543	    const external = findConflicts(store, t.resourceIds, t.startMin, t.endMin).filter(
1544	      (c) => !excludeBookingIds.has(c.booking.id),
1545	    );
1546	    const wanted = new Set(t.resourceIds);
1547	    const internal: BatchTargetFailure['internal'] = [];
1548	    for (let j = 0; j < targets.length; j++) {
1549	      if (j === i) continue;
1550	      const o = targets[j];
1551	      if (!(o.startMin < t.endMin && t.startMin < o.endMin)) continue;
1552	      const shared = o.resourceIds.filter((id) => wanted.has(id)).sort();
1553	      if (shared.length > 0) internal.push({otherIndex: j, shared});
1554	    }
1555	    if (gaps.length > 0 || external.length > 0 || internal.length > 0) {
1556	      failures.push({index: i, gaps, external, internal});
1557	    }
1558	  }
1559	  return failures;
1560	}
