1803	// 读取清单文件：不可读、不是合法 JSON 均明确失败（绝不按空清单处理）
1804	async function loadManifest(file: string): Promise<unknown> {
1805	  let text: string;
1806	  try {
1807	    text = await readFile(file, 'utf8');
1808	  } catch (err) {
1809	    throw new BizError(`无法读取改期清单 ${file}: ${(err as Error).message}`);
1810	  }
1811	  try {
1812	    return JSON.parse(text);
1813	  } catch (err) {
1814	    throw new BizError(`改期清单 ${file} 已损坏，不是合法 JSON：${(err as Error).message}`);
1815	  }
1816	}
