1818	// 清单结构（与数据文件无关的纯类型校验）；返回逐项原始记录
1819	function parseManifestShape(raw: unknown, file: string): Array<Record<string, unknown>> {
1820	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
1821	    throw new BizError(`改期清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
1822	  }
1823	  const o = raw as Record<string, unknown>;
1824	  for (const k of Object.keys(o)) {
1825	    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
1826	  }
1827	  if (!Array.isArray(o.items)) {
1828	    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
1829	  }
1830	  const items = o.items as unknown[];
1831	  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期安排`);
1832	
1833	  const problems: string[] = [];
1834	  const records: Array<Record<string, unknown> | null> = [];
1835	  items.forEach((it, idx) => {
1836	    const at = `第 ${idx + 1} 项`;
1837	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
1838	      problems.push(`${at} 必须是对象`);
1839	      records.push(null);
1840	      return;
1841	    }
1842	    const rec = it as Record<string, unknown>;
1843	    for (const k of Object.keys(rec)) {
1844	      if (k !== 'bookingId' && k !== 'start' && k !== 'end' && k !== 'resourceIds') {
1845	        problems.push(`${at} 存在未知字段 “${k}”（只允许 bookingId、start、end、resourceIds）`);
1846	      }
1847	    }
1848	    if (typeof rec.bookingId !== 'string' || rec.bookingId === '') {
1849	      problems.push(`${at} 的 bookingId 必须是非空字符串`);
1850	    }
1851	    if (typeof rec.start !== 'string' || rec.start === '') {
1852	      problems.push(`${at} 的 start 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1853	    }
1854	    if (typeof rec.end !== 'string' || rec.end === '') {
1855	      problems.push(`${at} 的 end 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1856	    }
1857	    if (!Array.isArray(rec.resourceIds)) {
1858	      problems.push(`${at} 的 resourceIds 必须是非空数组（完整目标资源集合，整体替换原集合）`);
1859	    } else {
1860	      if (rec.resourceIds.length === 0) problems.push(`${at} 的 resourceIds 不能为空：资源集合整体替换，至少一个资源`);
1861	      rec.resourceIds.forEach((rid, j) => {
1862	        if (typeof rid !== 'string' || rid === '') {
1863	          problems.push(`${at}.resourceIds[${j}] 必须是非空资源标识字符串`);
1864	        }
1865	      });
1866	    }
1867	    records.push(rec);
1868	  });
1869	  if (problems.length > 0) {
1870	    throw new BizError(`改期清单 ${file} 内容非法，整批拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1871	  }
1872	  return records as Array<Record<string, unknown>>;
1873	}
