1875	async function cmdRescheduleBatch(args: string[]): Promise<void> {
1876	  const {values, positionals} = parseFlags(args, []);
1877	  if (values.size > 0) {
1878	    throw new UsageError(
1879	      `reschedule-batch 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
1880	    );
1881	  }
1882	  if (positionals.length !== 1) {
1883	    throw new UsageError('用法: reschedule-batch <改期清单文件>');
1884	  }
1885	  const manifestFile = positionals[0];
1886	
1887	  const file = activeDataFile;
1888	  const store = await loadStoreForWrite(file);
1889	  const records = parseManifestShape(await loadManifest(manifestFile), manifestFile);
1890	
1891	  // 第一阶段：逐项做与业务数据相关的基础校验，收集全部问题后一次性拒绝整批
1892	  const problems: string[] = [];
1893	  const seenBooking = new Map<string, number>(); // 标识 -> 首次出现的序号（1 基）
1894	  const planned: Array<BatchTarget | null> = [];
1895	  records.forEach((rec, idx) => {
1896	    const at = `第 ${idx + 1} 项（${rec.bookingId as string}）`;
1897	    let ok = true;
1898	
1899	    const firstAt = seenBooking.get(rec.bookingId as string);
1900	    if (firstAt !== undefined) {
1901	      problems.push(`${at} 预约标识重复：该标识已在第 ${firstAt} 项出现，每项预约在清单中只能出现一次`);
1902	      ok = false;
1903	    } else {
1904	      seenBooking.set(rec.bookingId as string, idx + 1);
1905	    }
1906	
1907	    const booking = store.bookings.find((b) => b.id === rec.bookingId);
1908	    if (!booking) {
1909	      problems.push(`${at} 未知预约标识: ${rec.bookingId}`);
1910	      ok = false;
1911	    } else if (booking.status === 'cancelled') {
1912	      problems.push(`${at} 预约 ${booking.id} 已取消，不能改期`);
1913	      ok = false;
1914	    }
1915	
1916	    const rawRids = rec.resourceIds as string[];
1917	    const dupes = rawRids.filter((id, j) => rawRids.indexOf(id) !== j);
1918	    if (dupes.length > 0) problems.push(`${at} 资源重复指定: ${[...new Set(dupes)].join('、')}`);
1919	    const unknown = [...new Set(rawRids)]
1920	      .filter((id) => !store.resources.some((r) => r.id === id))
1921	      .sort();
1922	    if (unknown.length > 0) problems.push(`${at} 未知资源标识: ${unknown.join('、')}`);
1923	
1924	    let startMin = 0;
1925	    let endMin = 0;
1926	    let startParsed = false;
1927	    let endParsed = false;
1928	    try {
1929	      startMin = parseDateTime(rec.start as string, `${at} 目标开始时间`);
1930	      startParsed = true;
1931	    } catch (err) {
1932	      problems.push((err as BizError).message);
1933	    }
1934	    try {
1935	      endMin = parseDateTime(rec.end as string, `${at} 目标结束时间`);
1936	      endParsed = true;
1937	    } catch (err) {
1938	      problems.push((err as BizError).message);
1939	    }
1940	    if (startParsed && endParsed && endMin <= startMin) {
1941	      problems.push(
1942	        `${at} 目标结束时间必须晚于开始时间（开始: ${rec.start}，结束: ${rec.end}），允许跨日`,
1943	      );
1944	      ok = false;
1945	    }
1946	
1947	    if (!ok || !booking) {
1948	      planned.push(null);
1949	      return;
1950	    }
1951	    planned.push({
1952	      index: idx,
1953	      booking,
1954	      startRaw: rec.start as string,
1955	      endRaw: rec.end as string,
1956	      startMin,
1957	      endMin,
1958	      resourceIds: [...new Set(rawRids)].sort(),
1959	    });
1960	  });
1961	
1962	  if (problems.length > 0) {
1963	    throw new BizError(`改期清单 ${manifestFile} 校验失败，整批拒绝（原有安排保持不变）：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1964	  }
1965	  const targets = planned as BatchTarget[];
1966	  const batchIds = new Set(targets.map((t) => t.booking.id));
1967	
1968	  // 第二阶段：对“整批完成后”的安排做统一批次校验（无写入副作用）。
1969	  // 本批预约的旧占用一律不视为障碍（排除本批全部标识）；
1970	  // 障碍只来自本批之外的有效预约，以及本批各项的目标安排彼此之间。
1971	  const failures = validateBatchTargets(store, targets, batchIds);
1972	
1973	  if (failures.length > 0) {
1974	    // 按清单顺序报告全部不满足条件的项；批内冲突在双方项中都会出现
1975	    const blocks = failures.map((f) => {
1976	      const t = targets[f.index];
1977	      const lines = [`第 ${t.index + 1} 项 ${t.booking.id} 目标 ${t.startRaw} → ${t.endRaw}：`];
1978	      if (f.gaps.length > 0) {
1979	        lines.push('  开放不足资源:');
1980	        lines.push(...gapLines(f.gaps, '    '));
1981	      }
1982	      if (f.external.length + f.internal.length > 0) {
1983	        lines.push('  冲突预约:');
1984	        for (const c of f.external) {
1985	          lines.push(
1986	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
1987	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
1988	          );
1989	        }
1990	        for (const x of f.internal) {
1991	          const o = targets[x.otherIndex];
1992	          lines.push(
1993	            `    - ${o.booking.id}（本批第 ${o.index + 1} 项目标 ${o.startRaw} → ${o.endRaw}）` +
1994	              `：共同资源 ${formatResourceIds(store, x.shared)}`,
1995	          );
1996	        }
1997	      }
1998	      return lines.join('\n');
1999	    });
2000	    throw new BizError(
2001	      `批量改期失败：共 ${failures.length} 项不满足条件（按清单顺序），整批未改动：\n${blocks.join('\n')}`,
2002	    );
2003	  }
2004	
2005	  // 全部验证通过：一次性替换各项目标安排并原子落盘。
2006	  // 仅改时间与资源；标识、status、seriesId、标识计数全部不变，不创建任何预约或系列。
2007	  // 若保存失败，磁盘原文件保留；本进程亦以退出码 1 结束，不会报告成功。
2008	  // 资源集合均已按标识排序，按位比较即可
2009	  const sameArrangement = (t: BatchTarget): boolean =>
2010	    t.booking.start === t.startRaw &&
2011	    t.booking.end === t.endRaw &&
2012	    t.booking.resourceIds.length === t.resourceIds.length &&
2013	    t.booking.resourceIds.every((id, j) => id === t.resourceIds[j]);
2014	  const noChange = targets.every(sameArrangement);
2015	  if (noChange) {
2016	    // 幂等：提交的安排与现状完全一致时成功且不触碰数据文件；
2017	    // 不生成改期操作记录、不推进操作计数
2018	    console.log(
2019	      `批量改期成功：共 ${targets.length} 项，安排均与现状一致，无业务变化` +
2020	        '（标识与系列归属不变，未生成改期操作记录，数据文件与标识计数未改动）',
2021	    );
2022	    for (const t of targets) {
2023	      console.log(`第 ${t.index + 1} 项 ${t.booking.id}:`);
2024	      if (t.booking.seriesId) console.log(`  所属系列: ${t.booking.seriesId}（保持不变）`);
2025	      console.log(`  时间: ${t.startRaw} → ${t.endRaw}`);
2026	      console.log(`  资源: ${formatResourceIds(store, t.resourceIds)}`);
2027	    }
2028	    return;
2029	  }
2030	
2031	  // 至少一项有变化：在改动前抓取全部提交项的完整快照（标识、提交时系列归属、
2032	  // 改期前后时间与完整资源集合，顺序即清单顺序），生成一条“未撤销”操作记录，
2033	  // 与新安排在同一次原子保存中落盘后才报告成功；保存失败则不留记录、不推进计数。
2034	  const opItems: BatchOpItem[] = targets.map((t) => {
2035	    const item: BatchOpItem = {
2036	      bookingId: t.booking.id,
2037	      before: {
2038	        start: t.booking.start,
2039	        end: t.booking.end,
2040	        resourceIds: [...t.booking.resourceIds],
2041	      },
2042	      after: {start: t.startRaw, end: t.endRaw, resourceIds: [...t.resourceIds]},
2043	    };
2044	    if (t.booking.seriesId !== undefined) item.seriesId = t.booking.seriesId;
2045	    return item;
2046	  });
2047	  store.batchSeq += 1;
2048	  const opId = `O${String(store.batchSeq).padStart(4, '0')}`;
2049	  for (const t of targets) {
2050	    t.booking.start = t.startRaw;
2051	    t.booking.end = t.endRaw;
2052	    t.booking.resourceIds = t.resourceIds;
2053	  }
2054	  store.batchOps.push({id: opId, status: 'active', items: opItems});
2055	  await saveStore(file, store);
2056	
2057	  console.log(
2058	    `批量改期成功：操作标识 ${opId}，共 ${targets.length} 项（标识与系列归属不变，未创建预约或系列）`,
2059	  );
2060	  for (const t of targets) {
2061	    console.log(`第 ${t.index + 1} 项 ${t.booking.id}:`);
2062	    if (t.booking.seriesId) console.log(`  所属系列: ${t.booking.seriesId}（保持不变）`);
2063	    console.log(`  时间: ${t.startRaw} → ${t.endRaw}`);
2064	    console.log(`  资源: ${formatResourceIds(store, t.resourceIds)}`);
