2342	// 按周展开系列：每项相对前一项将起止时间同时后移 7 个营业地日历日，
2343	// 时刻与跨日长度保持不变。任何一项超出四位年份范围即整体拒绝。
2344	function planWeeklyMembers(startMin: number, endMin: number, count: number): PlannedMember[] {
2345	  const members: PlannedMember[] = [];
2346	  for (let i = 0; i < count; i++) {
2347	    const s = startMin + i * 7 * 1440;
2348	    const e = endMin + i * 7 * 1440;
2349	    const startRaw = formatDateTime(s);
2350	    const endRaw = formatDateTime(e);
2351	    if (startRaw === null || endRaw === null) {
2352	      const nth = i + 1;
2353	      throw new BizError(
2354	        `系列第 ${nth} 项（约第 ${nth} 周）的时间超出四位年份范围（${MIN_YEAR}-${MAX_YEAR}），无法创建：` +
2355	          '请缩短次数或改选更早的首项时间',
2356	      );
2357	    }
2358	    members.push({startRaw, endRaw, startMin: s, endMin: e});
2359	  }
2360	  return members;
2361	}
