3272	function unfoldIcalLines(text: string, bad: (reason: string) => never): string[] {
3273	  const lines: string[] = [];
3274	  for (const raw of text.split(/\r\n|\n/)) {
3275	    if (raw === '') continue;
3276	    if (raw.startsWith(' ') || raw.startsWith('\t')) {
3277	      if (lines.length === 0) bad('文件以折行续行开头，缺少被延续的内容行');
3278	      lines[lines.length - 1] += raw.slice(1);
3279	    } else {
3280	      lines.push(raw);
3281	    }
3282	  }
3283	  return lines;
3284	}
