3287	function parseContentLine(
3288	  line: string,
3289	  bad: (reason: string) => never,
3290	): {name: string; params: string[]; value: string} {
3291	  const colon = line.indexOf(':');
3292	  if (colon < 0) bad(`内容行缺少 “:”: “${line}”`);
3293	  const head = line.slice(0, colon);
3294	  const value = line.slice(colon + 1);
3295	  const segs = head.split(';');
3296	  if (!/^[A-Za-z0-9-]+$/.test(segs[0])) bad(`属性名非法: “${segs[0]}”`);
