3301	// 解码后再比较，因此同一 UID 的不同转义写法视为相同。
3302	function unescapeIcalText(value: string): string {
3303	  return value.replace(/\\(\\|[nN]|,|;)/g, (_all, ch: string) =>
3304	    ch === 'n' || ch === 'N' ? '\n' : ch,
