3353	// 解析 RRULE 值：仅支持 FREQ=WEEKLY 与 COUNT=n 两个部件（n 为 1..100000 的整数，
3354	// 含首项）；部件名大小写无关、顺序无关。空部件、重复部件、FREQ 其他取值、
3355	// INTERVAL/BYDAY/UNTIL 等任何其他部件一律拒绝。
3356	function parseWeeklyRrule(value: string, bad: (reason: string) => never): number {
3357	  const segs = value.split(';');
3358	  let freq: string | undefined;
3359	  let count: string | undefined;
3360	  for (const seg of segs) {
3361	    const eq = seg.indexOf('=');
3362	    if (eq <= 0) bad(`RRULE 部件格式非法: “${seg}”（应为 名称=值）`);
3363	    const name = seg.slice(0, eq).trim().toUpperCase();
3364	    const v = seg.slice(eq + 1).trim();
3365	    if (v === '') bad(`RRULE 部件 ${name} 的值不能为空`);
3366	    if (name === 'FREQ') {
3367	      if (freq !== undefined) bad('RRULE 的 FREQ 部件重复');
3368	      freq = v.toUpperCase();
3369	    } else if (name === 'COUNT') {
3370	      if (count !== undefined) bad('RRULE 的 COUNT 部件重复');
3371	      count = v;
3372	    } else {
3373	      bad(`不支持的 RRULE 部件 “${seg}”（仅支持 FREQ=WEEKLY 与 COUNT）`);
3374	    }
3375	  }
3376	  if (freq === undefined) bad('RRULE 缺少 FREQ 部件（仅支持 FREQ=WEEKLY）');
3377	  if (freq !== 'WEEKLY') bad(`仅支持按周重复 FREQ=WEEKLY，实际为 FREQ=${freq}`);
3378	  if (count === undefined) bad('RRULE 缺少 COUNT 部件（仅支持 FREQ=WEEKLY;COUNT=n）');
3379	  if (!/^\d+$/.test(count)) bad(`RRULE 的 COUNT 必须是整数: “${count}”`);
3380	  const n = Number(count);
3381	  if (n < 1 || n > MAX_OCCURRENCES) {
3382	    bad(`RRULE 的 COUNT 必须在 1..${MAX_OCCURRENCES} 之间（含首项）: “${count}”`);
3383	  }
3384	  return n;
