28	// ---------------------------------------------------------------------------
29	
30	interface CliResult {
31	  status: number;
32	  stdout: string;
33	  stderr: string;
34	}
35	
36	function runCli(dataFile: string, args: string[]): CliResult {
37	  const r = spawnSync(process.execPath, [APP, '--data', dataFile, ...args], {encoding: 'utf8'});
38	  if (r.error) throw r.error;
39	  return {status: r.status ?? -1, stdout: r.stdout ?? '', stderr: r.stderr ?? ''};
40	}
41	
42	function ok(df: string, args: string[], ctx: string): CliResult {
43	  const r = runCli(df, args);
44	  assert.equal(
45	    r.status,
46	    0,
47	    `[${ctx}] 期望退出 0，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
48	  );
49	  return r;
50	}
51	
52	function bizFail(df: string, args: string[], ctx: string): CliResult {
53	  const r = runCli(df, args);
54	  assert.equal(
55	    r.status,
56	    1,
57	    `[${ctx}] 期望退出 1，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
58	  );
59	  return r;
60	}
61	
62	function usageFail(df: string, args: string[], ctx: string): CliResult {
63	  const r = runCli(df, args);
64	  assert.equal(
65	    r.status,
66	    2,
67	    `[${ctx}] 期望退出 2，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
68	  );
69	  return r;
70	}
71	
72	function tempDir(t: {after: (fn: () => void) => void}): string {
73	  const dir = mkdtempSync(join(tmpdir(), 'shiftbook-find-slot-test-'));
74	  t.after(() => rmSync(dir, {recursive: true, force: true}));
75	  return dir;
76	}
77	
78	function addResource(
79	  df: string,
80	  name: string,
81	  open: Array<[string, string]> = OPEN_ALL,
82	  type = 'venue',
83	): void {
84	  const args = ['add-resource', '--type', type, '--name', name];
85	  for (const [s, e] of open) args.push('--open', `${s}/${e}`);
86	  ok(df, args, `登记资源 ${name}`);
87	}
88	
89	function findSlot(df: string, window: string, duration: string, groups: string[], ctx: string): CliResult {
90	  const args = ['find-slot', '--window', window, '--duration', duration];
91	  for (const g of groups) args.push('--group', g);
92	  return ok(df, args, ctx);
93	}
94	
95	function readStore(df: string): any {
96	  return JSON.parse(readFileSync(df, 'utf8'));
97	}
98	
99	function assertFileBytes(df: string, expected: Buffer, ctx: string): void {
100	  assert.ok(expected.equals(readFileSync(df)), `[${ctx}] 查询不得改动数据文件（逐字节比对）`);
101	}
102	
103	// 断言查询结果：起止时间与按需求组顺序的所选资源标识
104	function assertSlot(r: CliResult, start: string, end: string, picks: string[], ctx: string): void {
105	  assert.match(
106	    r.stdout,
107	    new RegExp(`最早可行时段: ${start} → ${end}`),
108	    `[${ctx}] 起止时间\nstdout:\n${r.stdout}`,
109	  );
110	  picks.forEach((id, i) => {
111	    assert.match(
112	      r.stdout,
113	      new RegExp(`第 ${i + 1} 组: ${id}（`),
114	      `[${ctx}] 第 ${i + 1} 组应选 ${id}\nstdout:\n${r.stdout}`,
115	    );
116	  });
117	}
118	
119	function assertNoSlot(r: CliResult, ctx: string): void {
120	  assert.match(r.stdout, /无解：窗口 /, `[${ctx}] 应明确提示无解\nstdout:\n${r.stdout}`);
121	  assert.ok(!r.stdout.includes('最早可行时段'), `[${ctx}] 无解不得给出时段\nstdout:\n${r.stdout}`);
122	}
