338	// ---------------------------------------------------------------------------
339	// 6. 用法错误（退出 2）与非法请求（退出 1）
340	// ---------------------------------------------------------------------------
341	
342	test('用法错误退出 2，非法请求退出 1，均不改动数据文件', (t) => {
343	  const dir = tempDir(t);
344	  const df = join(dir, 'data.json');
345	  addResource(df, '一号会议室'); // R0001
346	  const bytesBefore = readFileSync(df);
347	
348	  // 用法错误（退出 2）
349	  usageFail(df, ['find-slot', '--window', '2026-10-12T09:00/2026-10-12T12:00', '--duration', '60'], '缺少 --group');
350	  usageFail(df, ['find-slot', '--duration', '60', '--group', 'R0001'], '缺少 --window');
351	  usageFail(df, ['find-slot', '--window', '2026-10-12T09:00/2026-10-12T12:00', '--group', 'R0001'], '缺少 --duration');
352	  usageFail(
353	    df,
354	    ['find-slot', '--window', '2026-10-12T09:00/2026-10-12T12:00', '--duration', '60', '--group', 'R0001', '--bogus', 'x'],
355	    '未知选项',
356	  );
357	  usageFail(
358	    df,
359	    ['find-slot', '--window', '2026-10-12T09:00/2026-10-12T12:00', '--duration', '60', '--group', 'R0001', '多余参数'],
360	    '多余位置参数',
361	  );
362	
363	  // 非法请求（退出 1）
364	  const base = ['find-slot', '--window', '2026-10-12T09:00/2026-10-12T12:00', '--duration', '60'];
365	  let r = bizFail(df, [...base, '--group', 'R0001,R0009'], '未知资源');
366	  assert.match(r.stderr, /未知资源标识: R0009/);
367	  r = bizFail(df, [...base, '--group', 'R0001,R0001'], '组内重复');
368	  assert.match(r.stderr, /候选资源重复: R0001/);
369	  r = bizFail(df, [...base, '--group', ','], '空需求组');
370	  assert.match(r.stderr, /为空或含空项/);
371	  r = bizFail(df, ['find-slot', '--window', '2026-10-12T09:00/2026-10-12T12:00', '--duration', '0', '--group', 'R0001'], '时长为 0');
372	  assert.match(r.stderr, /时长非法/);
373	  r = bizFail(df, ['find-slot', '--window', '2026-10-12T09:00/2026-10-12T12:00', '--duration', '1.5', '--group', 'R0001'], '时长非整数');
374	  assert.match(r.stderr, /时长非法/);
375	  r = bizFail(df, ['find-slot', '--window', '2026-10-12T09:00/2026-10-12T10:00', '--duration', '120', '--group', 'R0001'], '时长超过窗口');
376	  assert.match(r.stderr, /超过窗口长度/);
377	  r = bizFail(df, ['find-slot', '--window', '2026-10-12T12:00/2026-10-12T09:00', '--duration', '60', '--group', 'R0001'], '窗口结束早于开始');
378	  assert.match(r.stderr, /结束时间必须晚于开始时间/);
379	  r = bizFail(df, ['find-slot', '--window', '2026-10-12T09:00', '--duration', '60', '--group', 'R0001'], '窗口缺结束');
380	  assert.match(r.stderr, /查询窗口格式非法/);
381	  r = bizFail(df, ['find-slot', '--window', '2026-02-30T09:00/2026-10-12T12:00', '--duration', '60', '--group', 'R0001'], '窗口日期不真实');
382	  assert.match(r.stderr, /不是真实有效的时间/);
383	
384	  assertFileBytes(df, bytesBefore, '全部失败请求后');
385	  const store = readStore(df);
386	  assert.equal(store.bookings.length, 0, '失败请求不产生记录');
387	});
388	
389	// ---------------------------------------------------------------------------
390	// 7. 数据文件损坏退出 1；旧格式数据文件继续可读（查询不补写字段）
391	// ---------------------------------------------------------------------------
392	
393	test('损坏文件退出 1 并保留原样；旧格式文件可直接查询且不改动', (t) => {
394	  const dir = tempDir(t);
395	
396	  // 损坏文件：退出 1，原样保留
397	  const bad = join(dir, 'bad.json');
398	  writeFileSync(bad, '{ not json', 'utf8');
399	  const badBytes = readFileSync(bad);
400	  const r1 = bizFail(bad, ['find-slot', '--window', '2026-10-12T09:00/2026-10-12T12:00', '--duration', '60', '--group', 'R0001'], '损坏文件');
401	  assert.match(r1.stderr, /已损坏/);
402	  assertFileBytes(bad, badBytes, '损坏文件查询失败后');
403	
404	  // 旧格式文件（只有 version 与 resources，无后续版本字段）：直接可查，查询不补写
405	  const old = join(dir, 'old.json');
406	  writeFileSync(
407	    old,
408	    JSON.stringify({
409	      version: 1,
410	      resources: [{id: 'R0001', type: 'venue', name: '旧会议室', open: [['2026-01-01T00:00', '2027-01-01T00:00']]}],
411	    }) + '\n',
412	    'utf8',
413	  );
414	  const oldBytes = readFileSync(old);
415	  const r2 = findSlot(old, '2026-10-12T09:00/2026-10-12T12:00', '60', ['R0001'], '旧文件查询');
416	  assertSlot(r2, '2026-10-12T09:00', '2026-10-12T10:00', ['R0001'], '旧文件查询');
417	  assert.match(r2.stdout, /R0001（旧会议室，场地）/, '显示标识、名称与类型');
418	  assertFileBytes(old, oldBytes, '旧文件查询后');
419	});
